from lib import *
S = SS('w75')
steps = [
    step("连接复用 vs 每次新建。本机服务器,lo0 上 netlab 每方向延迟 50 ms(往返 100 ms)。顺序取 10 个小资源:每个资源新建一条连接(Connection: close)总共 2024 ms,平均每个 202 ms,约等于 10 × (握手 1 个 RTT + 请求响应 1 个 RTT);在同一条连接上依次取(keep-alive)总共 1114 ms,平均 111 ms,约等于 1 次握手 + 10 个请求响应 = 11 个 RTT。省下 910 ms,约 9.1 个 RTT——复用连接省下的是除第一次之外每个资源的握手往返。", t=tl(S(1)), mark=lidx(S(1), '每次新建连接', '同一条连接上依次取'), done=lidx(S(1), '省下 910 ms'), b=bars([['每次新建连接 10 个', 2024, '2024 ms'], ['keep-alive 10 个', 1114, '1114 ms']], 2024, mark=[1], done=[0]), kv=KV([['每次新建', '2024 ms(≈ 20 个 RTT)'], ['keep-alive', '1114 ms(≈ 11 个 RTT)'], ['省下', '约 9.1 个 RTT']], ['省下'])),
    step("流水线(pipelining):不等响应就连续发出多个请求。同样 10 个资源,一次性全发出去再读 10 个响应:总共 233 ms(握手 1 RTT + 一次请求响应 1 RTT ≈ 200 ms,再加一点处理时间),第 1 个响应在握手完成后 100 ms,第 10 个在 133 ms。对比:不流水线的 keep-alive 要 1114 ms,每次新建要 2024 ms。流水线把 10 个请求塞进了一个往返里,延迟从 11 个 RTT 降到约 2 个。", t=tl(S(2)), mark=lidx(S(2), '流水线:10 个资源总共'), done=lidx(S(2), '对比'), b=bars([['每次新建', 2024, '2024 ms'], ['keep-alive 顺序', 1114, '1114 ms'], ['流水线', 233, '233 ms']], 2024, mark=[2], done=[0, 1]), kv=KV([['流水线 10 个', '233 ms'], ['第 1 个响应', '握手后 100 ms'], ['第 10 个响应', '握手后 133 ms']], ['流水线 10 个'])),
    step("流水线的致命问题——队头阻塞:响应必须按请求的顺序返回。第 1 个请求让服务器处理 600 ms,后面 4 个请求很快。流水线(服务端默认):5 个响应到达时刻 [702, 802, 802, 802, 802] ms;服务端开 TCP_NODELAY:[704, 704, 704, 704, 704] ms;对比 5 条并行连接:慢的 806 ms,另外 4 个都在 202 ms。三个结论:(1) 4 个快请求在流水线里被那个慢请求拖到 702~704 ms 以后才拿到,并行连接里只要 202 ms;(2) 服务端默认设置下,后 4 个响应比第 1 个又晚了 100 ms(= 一个 RTT),开了 TCP_NODELAY 就是 0 ms——前几篇讲的 Nagle:后面的小响应被扣到前一个响应的 ACK 回来才发;(3) 因为有这个队头阻塞,而且很多代理不支持,流水线在浏览器里基本没有被启用。", t=tl(S(3)), mark=lidx(S(3), '服务器默认(Nagle 开)', '服务器 TCP_NODELAY'), done=lidx(S(3), '5 条并行连接', '快请求在流水线里'), b=bars([['流水线 第 1 个(慢)', 702, '702 ms'], ['流水线 后 4 个(Nagle 开)', 802, '802 ms'], ['流水线 后 4 个(NODELAY)', 704, '704 ms'], ['并行连接 快的 4 个', 202, '202 ms']], 806, mark=[1], done=[0, 2, 3]), kv=KV([['流水线', '快请求被慢请求拖到 702~704 ms'], ['Nagle 开', '后 4 个又晚 100 ms'], ['并行连接', '快请求 202 ms']], ['流水线'])),
    step("真实服务器 example.com:80 能不能流水线?3 个请求一次发出,3 秒内收到 2799 字节,其中 \"HTTP/1.1 200 OK\" 状态行 3 个——它按顺序处理了全部 3 个请求并依次返回。也就是说 Cloudflare 的服务器端是支持流水线的;不用的原因不在服务器,而在浏览器和各种中间代理对流水线的支持参差不齐,加上上面的队头阻塞。", t=tl(S(4)), mark=lidx(S(4), '3 个请求一次发出'), done=lidx(S(4), '3 个请求一次发出'), kv=KV([['3 个请求一次发出', '收到 3 个 200 OK'], ['收到字节', '2799']], ['3 个请求一次发出'])),
    step("服务器多久关闭空闲的持久连接?连上 example.com:80,发一个请求(响应头 Connection: keep-alive,没有 Keep-Alive: timeout= 提示),然后什么也不做,每秒检查连接是否还开着。等了 130 秒,服务器一直没有关闭连接。所以这个服务器的空闲超时至少有 130 秒(上限没有继续测);客户端不能假设连接永远可用——中间的 NAT、防火墙、负载均衡随时可能把空闲连接丢掉,所以复用连接前要准备好失败重试(第 77 篇讲 HTTP 方法的幂等性)。", t=tl(S(5)), mark=lidx(S(5), '130 秒内服务器一直没有关闭连接'), done=lidx(S(5), '响应头里和连接有关的'), kv=KV([['空闲超时', '> 130 秒(没有等到关闭)'], ['Keep-Alive 头', '没有给出提示']], ['空闲超时'])),
]
A = mkartw('w75', 75, '网络协议,HTTP,HTTP/1.1,持久连接,keep-alive,流水线,队头阻塞,Nagle,真实验证,动画演示',
    '实测 HTTP/1.1 的连接复用:RTT 100 ms 时 10 个资源每次新建 2024 ms、keep-alive 1114 ms、流水线 233 ms;但流水线有队头阻塞:快请求被慢请求拖到 702 ms(并行连接只要 202 ms),服务端不开 TCP_NODELAY 还会再晚 100 ms;example.com 支持流水线且空闲 130 秒也不关连接。',
    '一个页面要取很多资源,每个资源都新建一条 TCP 连接太贵,所以有了持久连接和(曾经的)流水线。这篇在 100 ms 往返的链路上量:复用连接省了多少个往返、流水线又省了多少、它为什么没有被普遍使用——顺便抓到了一次真实的 Nagle 算法拖慢。',
    [('2024 → 1114 → 233 ms', '10 个资源:每次新建 / keep-alive 顺序 / 流水线 的总耗时(往返 100 ms)'), ('702 vs 202 ms', '流水线里快请求被慢请求拖住的时刻 与 并行连接里的到达时刻'), ('100 ms', '服务端不开 TCP_NODELAY 时,流水线后几个响应额外多等的时间(一个 RTT)')],
    [('复用连接', '<p>每次新建要 2 个 RTT,keep-alive 只要 1 个。10 个资源省下约 9 个 RTT。</p>'),
     ('流水线', '<p>不等响应连续发请求,10 个资源总共约 2 个 RTT。</p>'),
     ('队头阻塞', '<p>响应必须按请求顺序返回,第一个慢,后面的都得等;并行连接则互不影响。服务端不开 TCP_NODELAY 还会再慢一个 RTT。</p>'),
     ('真实服务器', '<p>example.com 能处理一次发出的 3 个流水线请求。</p>'),
     ('空闲超时', '<p>example.com 的持久连接空闲 130 秒仍未被关闭。</p>')],
    steps,
    [ENV_W + '。第一至三节用本机的 Python 服务器(线程,每个请求顺序处理)和 netlab(每方向 50 ms);第三节分别让服务端默认与 TCP_NODELAY;第四、五节是对 example.com:80 的明文 HTTP/1.1,第五节只等了 130 秒',
     '没有验证:浏览器每个主机的并发连接数(通常 6);HTTP/1.1 的 Keep-Alive: timeout/max 参数在别的服务器上的行为;连接被中间设备悄悄丢掉后客户端的表现;流水线遇到不支持它的代理时的失败方式;服务器对每条连接最大请求数的限制;第二节第 10 个响应比第 1 个晚 33 ms 的原因(没有查)'],
    '持久连接与流水线')
